const installation=new WeakMap()
export function syncGovernanceRepositories(state,fixtures,project,repositories,primary){
 repositories=[...repositories].sort((a,b)=>Number(b.path===primary)-Number(a.path===primary))
 const d=data('project-settings',{...state,project},fixtures),p=d.projectConfig,next=repositories.map(r=>r.path).join(', ')
 if(p.repos===next)return p.revision
 p.history.push({revision:p.revision,...configValues(p),reason:p.reason})
 p.repos=next;p.revision++;p.reason='Набор репозиториев изменён в проекте'
 const fixture=fixtures.projects.find(p=>p.id===project)
 if(fixture)Object.assign(fixture,{repo:primary,repos:repositories.map(r=>r.path),config_revision:p.revision})
 if(p.preview)p.conflict={base:p.preview.base,winning:configValues(p),draft:p.preview.values}
 return p.revision
}
