 function publishProject(c){const p=c.d.projectConfig,patch={name:p.name,purpose:p.purpose,repo:p.repos.split(',').map(x=>x.trim()).filter(Boolean)[0]||null,repos:p.repos.split(',').map(x=>x.trim()).filter(Boolean),config_revision:p.revision,targetScope:p.scope,targetProjects:(p.targets||'').split(',').map(x=>x.trim()).filter(Boolean),futureConsent:!!p.futureConsent,memoryPolicy:p.memoryPolicy};const fixture=c.d.fixtures?.projects?.find(x=>x.id===c.state.project);if(fixture)Object.assign(fixture,patch);c.d.projectName=p.name;onProjectChange(c.state.project,patch);publish(c,'project.config',patch)}
